    "content": "新华社伦敦11月22日电 记者手记｜从一则褪色广告看英欧“分合”往事 新华社记者张枫 距离英国伦敦大本钟约20分钟脚程，奥尔德威奇地铁站静静伫立。它于1907年投入运营，1994年正式停运，如今作为伦敦地铁遗迹面向公众开放。 历经百年风雨，奥尔德威奇地铁站曾见证英国民众在此躲避第二次世界大战的硝烟，也留下了英国与欧洲大陆关系变迁的历史印记。隧道内斑驳的墙壁上，一则略显褪色的《泰晤士报》广告，将人们的思绪带回半个多世纪前英国社会讨论加入欧洲共同体（欧共体）的年代。 “如果英国加入欧洲共同市场，你知道英国农民将获得多少…"
