    "description": "新华社北京11月22日电（记者刘慧）11月22日，调整融资保证金比例、创业板拟引入做市商制度、一揽子降费措施三项稳定资本市场相关政策公布。 经证监会批准，沪深北交易所将融资保证金比例下限从100%降低至80%，此次调整将自2026年11月30日起实施。据测算，此次调整理论上可带来增量资金近4000亿元。 专家指出，当融资保证金比例为100%，融资交易的杠杆倍数可达1倍。当融资保证金比例降至80%时，融资交易杠杆倍数可以达到1.25倍，可…",
    "content": "新华社北京11月22日电（记者刘慧）11月22日，调整融资保证金比例、创业板拟引入做市商制度、一揽子降费措施三项稳定资本市场相关政策公布。 经证监会批准，沪深北交易所将融资保证金比例下限从100%降低至80%，此次调整将自2026年11月30日起实施。据测算，此次调整理论上可带来增量资金近4000亿元。 专家指出，当融资保证金比例为100%，融资交易的杠杆倍数可达1倍。当融资保证金比例降至80%时，融资交易杠杆倍数可以达到1.25倍，可融资买入规模提升了25%，有利于吸引增量资金。融资保证金比例调整是实施逆周期调节…"
