    "description": "沪深交易所、中国结算集体降费。 11月22日，上海证券交易所（简称“上交所”）发布《关于进一步减免相关费用的通知》，推出新一批降费措施，包括免收交易单元使用费，减免数据中心相关服务费用等，并将今年初已发布的免收上市费、债券经手费等措施有效期再延长两年。 上交所表示，本次新推出的降费措施预计向市场让利13.68亿元，预计本年度沪市整体降费金额超过24亿元。 同日，深圳证券交易所（简称“深交所”）发布《关于进一步减免相关费用的通知》，也推出…",
