    "description": "中新网北京11月22日电 锦州地处辽宁省西南部，北依松岭山脉，南临渤海辽东湾，山、河、海在此地交汇，养出了锦州丰饶的海陆物产。大型风物美食文旅节目《寻味山海》21日晚在总台综合频道播出，观众跟随主持人走进辽宁锦州，品味山海相拥的滋味。",
    "content": "中新网北京11月22日电 锦州地处辽宁省西南部，北依松岭山脉，南临渤海辽东湾，山、河、海在此地交汇，养出了锦州丰饶的海陆物产。大型风物美食文旅节目《寻味山海》21日晚在总台综合频道播出，观众跟随主持人走进辽宁锦州，品味山海相拥的滋味。"
