    "content": "11月22日拍摄的停靠在广州南沙国际邮轮母港的“爱达·花城号”。新华社发 新华社广州11月22日电（记者周颖、邓瑞璇）中国第二艘国产大型邮轮“爱达·花城号”22日搭载3800余名宾客从广州南沙国际邮轮母港出发，开启前往香港、越南顺化6天5晚首航之旅。继“爱达·魔都号”之后，又一国产大型邮轮实现常态化商业运营，将有效激发中国海洋消费新活力。 “爱达·魔都号”是中国首艘国产大型邮轮，总吨位13.62万，自2024年1月首航起，至今已运营约250个航次。作为其姊妹船，“爱达·花城号”吨位更大、外形更修长。船体全长341米…"
