    "description": "新华社南昌11月22日电 中共江西省第十六届委员会第一次全体会议11月22日选举尹弘为省委书记，陈永奇、庄兆林为省委副书记，当选为省委常委的还有黄喜忠、时玉宝、盛秋平、陈敏、张莹（女）、刘金波、杨勇、许南吉、严允、陈克龙。 中共江西省第十六届纪委第一次全体会议选举时玉宝为省纪委书记，许朝杰、饶华东、郭素芳（女）、熊明为省纪委副书记。",
    "content": "新华社南昌11月22日电 中共江西省第十六届委员会第一次全体会议11月22日选举尹弘为省委书记，陈永奇、庄兆林为省委副书记，当选为省委常委的还有黄喜忠、时玉宝、盛秋平、陈敏、张莹（女）、刘金波、杨勇、许南吉、严允、陈克龙。 中共江西省第十六届纪委第一次全体会议选举时玉宝为省纪委书记，许朝杰、饶华东、郭素芳（女）、熊明为省纪委副书记。"
