    "description": "当记忆逐渐衰退，双手还能记住什么？在浦东惠南镇的“记忆菜园”里，或许能找到答案。 眼下正是收获的时节，菜园里一片绿油油，萝卜长得圆滚滚，青菜长得水灵灵。老人们正忙着在地里收菜。这些老人中，很多人正面临着认知衰退的风险，他们可能转眼就忘了刚做过的事，但只要一走到菜地里，一双手碰到泥土，什么时候该播种、什么时候该浇水，心里都清楚得很。 从一块地，到一桌菜；从一段记忆，到一份尊严。惠南镇的“忆耕蔬园”，是农村认知症友好社区建设的一次温情探索。…",
    "content": "当记忆逐渐衰退，双手还能记住什么？在浦东惠南镇的“记忆菜园”里，或许能找到答案。 眼下正是收获的时节，菜园里一片绿油油，萝卜长得圆滚滚，青菜长得水灵灵。老人们正忙着在地里收菜。这些老人中，很多人正面临着认知衰退的风险，他们可能转眼就忘了刚做过的事，但只要一走到菜地里，一双手碰到泥土，什么时候该播种、什么时候该浇水，心里都清楚得很。 从一块地，到一桌菜；从一段记忆，到一份尊严。惠南镇的“忆耕蔬园”，是农村认知症友好社区建设的一次温情探索。记忆或许会迷路，但泥土永远记得双手的温度。种下一颗种子，也种下一份对生命的温柔与…"
