    "content": "新华社巴黎11月22日电 中国女足国脚吴澄舒21日在法国女子足球甲级联赛第10轮比赛中替补登场，15分钟内连进三球，上演个人法甲生涯首个“帽子戏法”，帮助南特队客场4:2击败勒阿弗尔队。 南特队在第21分钟由布阿巴迪首开记录，勒阿弗尔队在第60分钟将比分扳成1:1。第69分钟，吴澄舒替补出场。 第84分钟，吴澄舒头球攻入加盟南特队后的首粒联赛进球。3分钟后，她再度建功，将比分扩大为3:1。 勒阿弗尔队在第90分钟扳回一球。补时第八分钟，吴澄舒再入一球，将比分锁定为4:2。 “纪念一下在法甲的第一个帽子戏法。”吴澄舒…"
