    "content": "新华社杭州11月22日电（记者牛梦彤、夏亮）2026年空手道世界杯22日在杭州落幕，中国女子团体组手队和女子团体型队分别战胜西班牙队、伊朗队，收获两枚铜牌，均创造各自项目在该项赛事中的历史最好成绩。 女子团体组手铜牌争夺战中，中国队王晨铃首回合与对手战平，龚莉出战第二回合遗憾告负。在关键的第三回合，亚运会冠军李巧巧顶住压力取胜，将双方获胜回合数扳为1:1，中国队最终凭借小分优势获胜。 “专注三分钟内的每一秒。”李巧巧赛后说，考虑到双方获胜回合数打平后需要比较小分，她提醒自己即使领先也不能放松，要尽可能为全队提高获胜…"
