    "pub_date": "2026-11-22 18:58:39",
    "author": "",
    "description": "记者今天从国家开发银行了解到，国开行目前已全面完成所承办的2026年度国家助学贷款发放工作，共向753万名家庭经济困难学生发放国家助学贷款1163亿元。贷款学生可通过国家开发银行助学贷款学生在线系统(https://sls.cdb.com.cn)或国家助学贷款手机客户端查询发放结果。",
    "content": "记者今天从国家开发银行了解到，国开行目前已全面完成所承办的2026年度国家助学贷款发放工作，共向753万名家庭经济困难学生发放国家助学贷款1163亿元。贷款学生可通过国家开发银行助学贷款学生在线系统(https://sls.cdb.com.cn)或国家助学贷款手机客户端查询发放结果。"
