    "description": "11月21日至22日，2026脑机接口大会开幕式及多场论坛在北京市昌平区举办。会上发布了《脑机接口创新发展研究报告（2026）》。报告认为，2026年，全球脑机接口取得新进展，企业数量实现较快增长。同时，行业格局出现新变化，信息通信和医疗行业头部企业开始进入赛道。 报告显示，2026年全球脑机接口企业数量从800多家增至1175家，相比2025年实现了较快增长。我国脑机接口产业集聚于京津冀、长三角、粤港澳三大城市群，共集聚190余家企业…",
    "content": "11月21日至22日，2026脑机接口大会开幕式及多场论坛在北京市昌平区举办。会上发布了《脑机接口创新发展研究报告（2026）》。报告认为，2026年，全球脑机接口取得新进展，企业数量实现较快增长。同时，行业格局出现新变化，信息通信和医疗行业头部企业开始进入赛道。 报告显示，2026年全球脑机接口企业数量从800多家增至1175家，相比2025年实现了较快增长。我国脑机接口产业集聚于京津冀、长三角、粤港澳三大城市群，共集聚190余家企业，占全国的77.4%。 《脑机接口创新发展研究报告（2026）》发布现场。（主办…"
