    "content": "融资保证金比例从100%降至80%。 11月22日，为加强融资融券逆周期调节，促进融资融券业务健康平稳发展，经中国证监会批准，沪深北交易所发布《关于调整融资保证金比例等相关安排的通知》（下称“《通知》”），将融资保证金比例下限从100%降低至80%。 此次调整有一周过渡期，将自2026年11月30日起实施。 融资保证金比例调整是实施融资融券逆周期调节的重要工具之一，历史上曾多次运用，且历次调整均在市场形势关键节点出台。例如，2023年8月下调融资保证金比例至80%、2026年1月上调融资保证金比例至100%。 当前…"
