    "description": "新华社北京11月22日电 题：怎样从“晚起半小时”到“真正睡得好” 新华社记者周思宇、柯高阳、俞菀 清晨天微亮，孩子在睡眼惺忪中穿衣、洗漱；来不及吃完饭，往兜里塞颗鸡蛋就匆匆出门……曾经让不少家庭头疼的“孩子睡不够、家长送学早”问题，随着多地推行延迟到校得到改善。从“晚起半小时”到“真正睡得好”，保障儿童青少年的睡眠时长，助力孩子身心健康发展，是一道需要家庭、学校、社会协同作答的课题。 多地推行延迟到校 “按照规范办学相关要求，为切实保…",
    "content": "新华社北京11月22日电 题：怎样从“晚起半小时”到“真正睡得好” 新华社记者周思宇、柯高阳、俞菀 清晨天微亮，孩子在睡眼惺忪中穿衣、洗漱；来不及吃完饭，往兜里塞颗鸡蛋就匆匆出门……曾经让不少家庭头疼的“孩子睡不够、家长送学早”问题，随着多地推行延迟到校得到改善。从“晚起半小时”到“真正睡得好”，保障儿童青少年的睡眠时长，助力孩子身心健康发展，是一道需要家庭、学校、社会协同作答的课题。 多地推行延迟到校 “按照规范办学相关要求，为切实保障学生睡眠时间，我校学生到校时间为早上8点以后。”近期，江苏多地家长收到了学校关…"
