    "category": "新闻",
    "title": "特稿：蓝白破局派系角力错综复杂 新竹县蓝绿有得拼",
    "link": "https://www.zaobao.com.sg/news/china/story20261122-9930146",
    "pub_date": "2026-11-22 18:14:20",
    "author": "",
    "description": "今年台湾九合一选举，在野的国民党与民众党之间的合作是一大看点。然而，两党在竹北市长选举整合破局，加上蓝营内部分裂，为长期由蓝营执政的新竹县选情增添变数，使这个传统蓝营优势选区出现政党轮替的可能。 家住竹北市、加入国民党数十年的基层小组长邱女士，早前参加国民党举行的桃园、新竹县市及苗栗跨县市联合造势活动。她对新竹县选情颇感忧心，认为民进党提名的郑朝方“是一个来势汹汹的对手”。 她告诉《联合早报》，郑朝方过去四年担任竹北市长，施政获得当地居…",
    "content": "今年台湾九合一选举，在野的国民党与民众党之间的合作是一大看点。然而，两党在竹北市长选举整合破局，加上蓝营内部分裂，为长期由蓝营执政的新竹县选情增添变数，使这个传统蓝营优势选区出现政党轮替的可能。 家住竹北市、加入国民党数十年的基层小组长邱女士，早前参加国民党举行的桃园、新竹县市及苗栗跨县市联合造势活动。她对新竹县选情颇感忧心，认为民进党提名的郑朝方“是一个来势汹汹的对手”。 她告诉《联合早报》，郑朝方过去四年担任竹北市长，施政获得当地居民肯定，“对地方的建设，他做得也是有口皆碑”。 蓝营地方派系角力 绿营乘虚而入 …"
