    "content": "中国科技巨头华为推出全新子品牌OSTA星芒，并发布首款搭载鸿蒙7操作系统的人工智能（AI）手机OSTA O1 Pro，售价从5699元（人民币，下同，约1040新元）起。 综合华尔街见闻和IT之家报道，华为星期五（11月20日）在鸿蒙智行享界V8及星芒品牌发布会上，正式推出OSTA星芒品牌及首款产品OSTA O1 Pro。 新机定位为鸿蒙AI手机，首次搭载HarmonyOS 7 AI先锋版，主打全新的AI交互体验。华为称，新系统支持开屏即用的AI交互功能，并具备系统级主动智能能力，可根据用户需求提供个性化服务。 硬…"
