    "description": "新华社雅加达11月22日电（记者李嘉聪）印度尼西亚警方22日表示，该国万丹省一糖果厂21日晚发生的火灾仍未完全扑灭，救援人员已从现场整理出7个尸袋，另有约50人失联。 发生火灾的糖果厂位于万丹省西冷县。工厂方面称，事发时共有约300人在场。当地警方说，由于火势猛烈，遇难者遗体已无法通过外观辨认。 当地警方称，部分建筑有坍塌风险，搜救工作面临困难，起火原因正在调查中。 这是11月22日在印度尼西亚万丹省拍摄的糖果厂火灾现场（无人机照片）。…",
    "content": "新华社雅加达11月22日电（记者李嘉聪）印度尼西亚警方22日表示，该国万丹省一糖果厂21日晚发生的火灾仍未完全扑灭，救援人员已从现场整理出7个尸袋，另有约50人失联。 发生火灾的糖果厂位于万丹省西冷县。工厂方面称，事发时共有约300人在场。当地警方说，由于火势猛烈，遇难者遗体已无法通过外观辨认。 当地警方称，部分建筑有坍塌风险，搜救工作面临困难，起火原因正在调查中。 这是11月22日在印度尼西亚万丹省拍摄的糖果厂火灾现场（无人机照片）。新华社发（维里摄） 这是11月22日在印度尼西亚万丹省拍摄的糖果厂火灾现场。新华…"
