    "pub_date": "2026-11-22 17:38:17",
    "author": "",
    "description": "在坦桑尼亚国家博物馆的一场绘画展上，索罗蒙·姆瓦卡桑加在一幅画前停下脚步。 画中是半个多世纪前的坦赞铁路工地。1970年，年轻的姆瓦卡桑加参加了铁路建设。回忆那段日子，他记得的不只是艰苦的工作，还有那些远道而来的中国工人。 “中国兄弟们不要求特殊照顾，同我们吃一样的清汤和玉米糊，住在同样的工地里。”姆瓦卡桑加说，当时坦中工人语言不通，交流是件麻烦事。为了方便施工，也为了安全，他们慢慢摸索出一套自己的办法：斯瓦希里语、中文，再加上手势，喊…",
    "content": "在坦桑尼亚国家博物馆的一场绘画展上，索罗蒙·姆瓦卡桑加在一幅画前停下脚步。 画中是半个多世纪前的坦赞铁路工地。1970年，年轻的姆瓦卡桑加参加了铁路建设。回忆那段日子，他记得的不只是艰苦的工作，还有那些远道而来的中国工人。 “中国兄弟们不要求特殊照顾，同我们吃一样的清汤和玉米糊，住在同样的工地里。”姆瓦卡桑加说，当时坦中工人语言不通，交流是件麻烦事。为了方便施工，也为了安全，他们慢慢摸索出一套自己的办法：斯瓦希里语、中文，再加上手势，喊一句，比一下。姆瓦卡桑加管它叫“坦赞铁路语”。 这是中、坦、赞工人、技术人员在一…"
