    "content": "逸飞激光公告称，公司控股股东、实际控制人、董事长兼总经理吴轩于2026年11月22日提议公司以自有资金和/或自筹资金，通过上交所集中竞价方式回购A股股份，回购股份用于维护公司价值及股东权益。本次拟回购资金总额不低于1.00亿元、不超过2.00亿元，回购价格不高于董事会审议通过回购方案决议前20个交易日公司股票均价的150%，回购期限为董事会审议通过回购方案之日起3个月内。吴轩承诺将推动公司尽快召开董事会审议回购事项，并对回购议案投赞成票，其及一致行动人提议前6个月内无买卖公司股份情况，回购期间暂无增减持计划。本次回…"
