    "description": "新华社洛杉矶11月21日电 据美国加利福尼亚州当地媒体21日报道，当晚该州图莱里县一场大型聚会现场发生枪击事件，造成9人受伤，其中2人伤势危重。 报道援引图莱里县治安官办公室的消息称，枪击发生时，一场有100余人参加的私人音乐会正在进行。 报道称，这起枪击事件似乎与帮派有关。事件的具体原因尚未公布。",
