    "description": "私自放水、随意改造管道、加装循环泵……这些行为会打乱热力系统的水力平衡，对整栋楼甚至整个小区的用户取暖造成影响。热电供热服务中心工作人员提示，如遇家中供热问题，可联系专业人员上门处理。 记者：赵玉和、王艳 新华社音视频部制作",
    "content": "私自放水、随意改造管道、加装循环泵……这些行为会打乱热力系统的水力平衡，对整栋楼甚至整个小区的用户取暖造成影响。热电供热服务中心工作人员提示，如遇家中供热问题，可联系专业人员上门处理。 记者：赵玉和、王艳 新华社音视频部制作"
