    "title": "英国等11国加入北约“卫星联合发射计划”",
    "link": "http://www.news.cn/20261122/47db3a462bd940a0a30287e87b6d30d9/c.html",
    "pub_date": "2026-11-22 16:36:59",
    "author": "",
    "description": "新华社北京11月22日电 英国政府官方网站22日发布通告称，英国已与德国、加拿大等其他10国共同签署文件，加入由北约主导的“卫星联合发射计划”，以获取“可靠、灵活”的卫星发射服务，并依托太空产业拉动经济增长。 该通告称，北约“卫星联合发射计划”旨在依托商业卫星发射服务商与基础设施，在签约国领土内打造卫星发射网络，构建韧性更强、响应更迅速、性价比更高的入轨通道。 这是2025年11月5日在比利时首都布鲁塞尔拍摄的北约总部大楼外的北约及成员…",
    "content": "新华社北京11月22日电 英国政府官方网站22日发布通告称，英国已与德国、加拿大等其他10国共同签署文件，加入由北约主导的“卫星联合发射计划”，以获取“可靠、灵活”的卫星发射服务，并依托太空产业拉动经济增长。 该通告称，北约“卫星联合发射计划”旨在依托商业卫星发射服务商与基础设施，在签约国领土内打造卫星发射网络，构建韧性更强、响应更迅速、性价比更高的入轨通道。 这是2025年11月5日在比利时首都布鲁塞尔拍摄的北约总部大楼外的北约及成员国旗帜。新华社记者张兆卿摄 据北约官网17日通报，北约主导的多国太空倡议“卫星联…"
