    "content": "11月17日晚间，浙江足球俱乐部和申花足球俱乐部先后在社交媒体上透露，浙江U15队球员朱宏轩在“钱潮杯”国际青少年足球邀请赛中遭遇重伤。 11月22日上午，上海申花足球俱乐部联系安排了华山医院神经外科创伤中心专家虞剑教授，在俱乐部青训总监严翔的陪同下专程赶赴杭州，给受伤的球员朱宏轩会诊。 浙江队此前在社交媒体上透露，11月8日晚，浙江U15队球员朱宏轩在比赛中头部遭剧烈撞击后失去意识，浑身抽搐，口鼻大量出血，我俱乐部配合组委会第一时间开展应急处置。经现场急救和医院多次检查诊断，朱宏轩头部大面积多发性骨折，并伴有脑脊…"
