    "author": "",
    "description": "新华社北京11月22日电 记者11月22日从中国铁建股份有限公司了解到，北京108新线高速公路重难点工程建设取得新进展，两条隧道分别实现双线和单线贯通，为这条北京西部山区“三横三纵”生命线主通道早日通车运营奠定坚实基础。 黑龙关1号隧道和牛角胡隧道均位于北京市房山区境内，分别由中铁十四局和中铁十六局承建。其中，实现双线贯通的黑龙关1号隧道地处深山峡谷，隧道出口与佛子庄大桥相连，下方跨越108国道复线和大石河，高差超过100米。实现单线贯…",
    "content": "新华社北京11月22日电 记者11月22日从中国铁建股份有限公司了解到，北京108新线高速公路重难点工程建设取得新进展，两条隧道分别实现双线和单线贯通，为这条北京西部山区“三横三纵”生命线主通道早日通车运营奠定坚实基础。 黑龙关1号隧道和牛角胡隧道均位于北京市房山区境内，分别由中铁十四局和中铁十六局承建。其中，实现双线贯通的黑龙关1号隧道地处深山峡谷，隧道出口与佛子庄大桥相连，下方跨越108国道复线和大石河，高差超过100米。实现单线贯通的牛角胡隧道多处穿越五级围岩破碎带，岩体松散、围岩自稳能力差，面临复杂地质条件…"
