    "description": "新华社北京11月22日电（记者余佩璇、鲍赫）你还记得美国白蛾吗？两个月前，街边行道树上、小区绿化带随处可见浑身覆着白丝绒毛毛虫，枝头挂起一团团白色虫幕，走在树下一不小心还会落在身上，扰了不少人的日常，那正是美国白蛾的幼虫高发期。随着气温转凉，身边的“毛毛虫”不见了，但它们并未消失，而是进入化蛹越冬阶段，悄悄藏匿起来。 近日，北京多个委办局、高校、区陆续启动清蛹行动，一场“挖蛹大战”正在铺开。为什么要赶在这个时节“埋头挖蛹”？怎样精准识别…",
