    "description": "从“太极之乡”邯郸广府古城到古建林立的石家庄正定古城，海外博主耶果和主持人在高墙古塔与灯火阑珊间，探索智能科技对历史古迹的精准守护。 在有着 2600 余年历史的邯郸广府古城，太极文化绵延传承，街巷古迹历久弥新。无人机与智能机器狗空地协同巡检，供电线缆引入地下，电表箱仿古改造，现代科技与历史古迹和谐相融，守护着古城的烟火日常。 行至石家庄正定古城，古塔耸立，古建荟萃。“古建 e 览”数字化小程序为全县重点古建筑建立数字化档案，高可靠性供…",
