    "description": "新华社香港11月22日电 香港特区政府财政司司长陈茂波22日发表网志表示，中方在亚太经合组织（APEC）工商领导人峰会上提出支持成立世界湾区经济合作联盟，深化各湾区交流互动，探索亚太经济合作新路径，为具备内联外通独特优势的香港提供更好发挥优势的机会。 陈茂波说，湾区经济具有开放性、协同性和外溢性，而亚太地区汇集了世界上最重要的一些湾区。联盟可把这些特质进一步联结起来，为区域经济合作搭建新平台、开拓新空间。 陈茂波表示，香港作为粤港澳大湾…",
    "content": "新华社香港11月22日电 香港特区政府财政司司长陈茂波22日发表网志表示，中方在亚太经合组织（APEC）工商领导人峰会上提出支持成立世界湾区经济合作联盟，深化各湾区交流互动，探索亚太经济合作新路径，为具备内联外通独特优势的香港提供更好发挥优势的机会。 陈茂波说，湾区经济具有开放性、协同性和外溢性，而亚太地区汇集了世界上最重要的一些湾区。联盟可把这些特质进一步联结起来，为区域经济合作搭建新平台、开拓新空间。 陈茂波表示，香港作为粤港澳大湾区的重要一员，也以“中国香港”名义参与APEC，与其他经济体在经贸与人文层面有着…"
