    "description": "中国第二艘国产大型邮轮“爱达·花城号”首航，实现常态化商业运营。 据新华社报道，“爱达·花城号”星期天（11月22日）搭载3800余名宾客从广州南沙国际邮轮母港出发，开启前往香港、越南顺化六天五晚首航之旅。 作为姊妹船，“爱达·花城号”比“爱达·魔都号”吨位更大、外形更修长。船体全长341米、总吨位14.19万，拥有2130间舱房、满载可容纳5232名宾客。 2027年，“爱达·花城号”将以广州为邮轮母港运营50余个国际航次，航线产品兼…",
    "content": "中国第二艘国产大型邮轮“爱达·花城号”首航，实现常态化商业运营。 据新华社报道，“爱达·花城号”星期天（11月22日）搭载3800余名宾客从广州南沙国际邮轮母港出发，开启前往香港、越南顺化六天五晚首航之旅。 作为姊妹船，“爱达·花城号”比“爱达·魔都号”吨位更大、外形更修长。船体全长341米、总吨位14.19万，拥有2130间舱房、满载可容纳5232名宾客。 2027年，“爱达·花城号”将以广州为邮轮母港运营50余个国际航次，航线产品兼顾短途休闲与中长线深度探索，串联起越南、马来西亚、文莱等多个目的地。 广州市文化…"
