    "description": "11月17日在京发布的《2026中国北斗产业发展指数报告》显示，截至2026年上半年，我国各种类型的北斗终端设备（不含消费类电子）应用数量接近4200万台/套，较去年同期增加近900万台/套，同比增长约27%，北斗综合应用渗透率超过90%。 策划：邹伟 主编：吴晶、孙闻、许晟 记者：顾天成、唐兴 编导：江柯 新华社国内部出品",
    "content": "11月17日在京发布的《2026中国北斗产业发展指数报告》显示，截至2026年上半年，我国各种类型的北斗终端设备（不含消费类电子）应用数量接近4200万台/套，较去年同期增加近900万台/套，同比增长约27%，北斗综合应用渗透率超过90%。 策划：邹伟 主编：吴晶、孙闻、许晟 记者：顾天成、唐兴 编导：江柯 新华社国内部出品"
