    "content": "台湾艺人欧阳娜娜在一档大陆节目中称，“总想着有一天海峡会变窄”。 据中新社报道，芒果TV、湖南卫视制作的节目《声生不息·天涯共此时》首期星期五（11月20日）播出，欧阳娜娜有一段70秒独白。 她提到，爷爷欧阳林生一直叮嘱她“要守住根”。 欧阳娜娜说，在江西吉安的家族祠堂里，亲眼看见了爷爷欧阳林生的名字，才真正理解长辈心中那份对故乡的牵挂。“总想着有一天海峡会变窄，窄到想念的人能牵着手一起走过。” 欧阳娜娜的父亲欧阳龙曾经担任国民党发言人。她身兼大提琴演奏者、影视演员、歌手等角色，2014年出演《北京爱情故事》在中国…"
