    "content": "新华社伦敦11月21日电（记者马邦杰）英超联赛第11轮在21日进行多场较量，“领头羊”阿森纳队在客场以2:2战平纽卡斯尔联队，未能进一步扩大榜首优势。 阿森纳开场后占据一定主动，第33分钟，埃泽接哈弗茨传球破门，帮助客队取得领先。易边再战，纽卡加强攻势，第49分钟，奥苏拉助攻巴恩斯扳平比分。第62分钟，蒂奥利用角球机会破门，帮助主队反超。第78分钟，马杜埃凯为阿森纳攻入扳平一球，双方最终2:2握手言和。 排名第三的曼城本轮主场1:1战平富勒姆。第16分钟，富勒姆由穆尼斯首开记录，曼城中场安德森第57分钟凌空抽射扳平…"
