    "description": "一个17岁的姑娘，怎么就成了中俄两国人民心中共同的英雄？最近跟随中俄联合采访团来到黑龙江省牡丹江市绥芬河市，看到一座带翅膀的雕像，很多路过的人会好奇，这个挥舞着头巾的姑娘是谁？她叫嘎丽娅，是被中俄两国共同铭记的反法西斯英雄，大家也称她为“和平天使”。 作者：张玥、陈渝 新华社音视频部制作",
    "content": "一个17岁的姑娘，怎么就成了中俄两国人民心中共同的英雄？最近跟随中俄联合采访团来到黑龙江省牡丹江市绥芬河市，看到一座带翅膀的雕像，很多路过的人会好奇，这个挥舞着头巾的姑娘是谁？她叫嘎丽娅，是被中俄两国共同铭记的反法西斯英雄，大家也称她为“和平天使”。 作者：张玥、陈渝 新华社音视频部制作"
