    "pub_date": "2026-11-22 15:09:52",
    "author": "",
    "description": "新华社东京11月22日电（记者钱铮 梁晨）欧洲和日本合作的“比皮科伦坡”水星探测计划22日确认，历经8年长途飞行，该探测计划的两个水星探测器已进入环水星轨道。 “比皮科伦坡”国际水星探测计划社交媒体官方账号发布消息说，地面控制人员已和探测器建立联系，确认探测器已被水星引力捕获，进入环水星轨道。 “比皮科伦坡”是欧洲航天局和日本宇宙航空研究开发机构的合作项目，所携的两个水星探测器于2018年10月20日启程飞赴水星。其中，欧航局研发的“水…",
    "content": "新华社东京11月22日电（记者钱铮 梁晨）欧洲和日本合作的“比皮科伦坡”水星探测计划22日确认，历经8年长途飞行，该探测计划的两个水星探测器已进入环水星轨道。 “比皮科伦坡”国际水星探测计划社交媒体官方账号发布消息说，地面控制人员已和探测器建立联系，确认探测器已被水星引力捕获，进入环水星轨道。 “比皮科伦坡”是欧洲航天局和日本宇宙航空研究开发机构的合作项目，所携的两个水星探测器于2018年10月20日启程飞赴水星。其中，欧航局研发的“水星行星轨道飞行器”主要用于探测水星的表面和组成，日本宇宙航空研究开发机构研发的“…"
