    "author": "",
    "description": "11月20日，首届历史经典产业博览会在杭州启幕。丝绸、茶叶、瓷器、中药、酿造、工艺美术等行业集中亮相……这些镌刻着中华文明印记的古老手艺，承载着中华民族文化的根脉。当传统技艺遇上现代科技、对接新的消费场景，它们如何焕发新的光彩？让我们跟随新华社记者奔赴产业一线，看看这些历史经典产业的新故事。 ■景德镇陶瓷：千年瓷都的多元蝶变 以前说景德镇，第一反应是好看，艺术瓷摆在那里，看的是手上功夫。现在不一样了，你会发现它多了两样东西：好玩、好用。…",
    "content": "11月20日，首届历史经典产业博览会在杭州启幕。丝绸、茶叶、瓷器、中药、酿造、工艺美术等行业集中亮相……这些镌刻着中华文明印记的古老手艺，承载着中华民族文化的根脉。当传统技艺遇上现代科技、对接新的消费场景，它们如何焕发新的光彩？让我们跟随新华社记者奔赴产业一线，看看这些历史经典产业的新故事。 ■ 景德镇陶瓷：千年瓷都的多元蝶变 以前说景德镇，第一反应是好看，艺术瓷摆在那里，看的是手上功夫。现在不一样了，你会发现它多了两样东西：好玩、好用。 在景德镇陶玩里潮玩空间，设计师运用AI根据“钟馗+潮玩+小鬼”生成设计方案，…"
