    "content": "新华社意大利都灵11月21日电&nbsp;2026年男子职业网球选手协会（ATP）年终总决赛半决赛21日战罢，西班牙名将阿尔卡拉斯、德国名将兹维列夫分别击败各自对手，会师决赛。 11月21日，阿尔卡拉斯庆祝胜利。新华社记者 李京 摄 二号种子阿尔卡拉斯当天对阵美国选手谢尔顿。首盘比赛，谢尔顿凭借出色的发球和进攻表现，以6:3先下一城。随后阿尔卡拉斯逐渐找回状态，以6:3扳回一盘。决胜盘双方展开激烈争夺，比赛进入“抢七”，阿尔卡拉斯以7:1的绝对优势获胜，连续第二年闯入年终总决赛决赛。 阿尔卡拉斯赛后说：“我真的非常…"
