    "content": "新华社北京11月22日电（记者王镜宇、王梦）米兰冬奥会冠军宁忠岩22日接受新华社记者专访时表示，能在速度滑冰世界杯日本带广站战胜美国名将乔丹·斯托尔兹夺冠，自己比之前在北京站夺冠时更兴奋，因为强大的对手逼出了更好的自己。 上周结束的北京站比赛，宁忠岩获得男子1000米和1500米两枚金牌。但斯托尔兹缺席了本站比赛，这对于宁忠岩来说，留下了一点遗憾。 带广站比赛是宁忠岩本赛季首次与斯托尔兹同场竞技。在21日的男子1500米比赛中，宁忠岩战胜斯托尔兹并夺冠，重现了在米兰冬奥会上与他巅峰对决的表现。 “说实话，能在150…"
