    "content": "近日，吉林省吉林市松花江畔迎来雾凇美景。十里长堤银装素裹，玉树琼枝宛若仙境。游客们纷纷驻足拍照，记录下这唯美瞬间。 记者：王帆、颜麟蕴 新华社音视频部制作 视频来源：吉林市融媒体中心"
