    "pub_date": "2026-11-22 14:34:32",
    "author": "",
    "description": "《参考消息》11月22日刊发的英国《金融时报》网站报道《是时候向中国表达感激了》。 每年差不多在这个时候，孩子们都会走到邮筒前，给圣诞老人寄一封百般讨好的信。既然如此，下一代人或许应该考虑开创一个新传统：给中国寄一张感谢卡。在拯救地球未来、更不用说保住白色圣诞节这件事上，没有哪个国家比中国做得更多。 新华社音视频部制作",
    "content": "《参考消息》11月22日刊发的英国《金融时报》网站报道《是时候向中国表达感激了》。 每年差不多在这个时候，孩子们都会走到邮筒前，给圣诞老人寄一封百般讨好的信。既然如此，下一代人或许应该考虑开创一个新传统：给中国寄一张感谢卡。在拯救地球未来、更不用说保住白色圣诞节这件事上，没有哪个国家比中国做得更多。 新华社音视频部制作"
